commands.command:
mkdir -p /etc/keepalived; cat > /etc/keepalived/keepalived.conf <<'EOF'
global_defs {
   router_id node1
   vrrp_skip_check_adv_addr
   vrrp_garp_master_refresh 5
}

vrrp_instance VI_SHARED {
    state MASTER
    interface br-lan
    virtual_router_id 51
    priority 150
    advert_int 1
    authentication {
        auth_type PASS
        auth_pass antrieb1
    }
    virtual_ipaddress {
        10.100.232.250/24 dev br-lan
    }
}
EOF
cat /etc/keepalived/keepalived.conf

